constructor(element?: string | Element | null, config?: Partial<DatepickerConfig> | null) {
  super(element, config)

  this._calendar = null
  this._isShown = false

  // Add Tab key listener in capture phase to allow tabbing out of datepicker
  this._onTabKey = (event: KeyboardEvent) => {
    if (event.key === 'Tab' && this._isShown) {
      this.hide()
    }
  }
  this._element.addEventListener('keydown', this._onTabKey, true)

  this._initCalendar()
}

